"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[815],{9255:e=>{e.exports=JSON.parse('{"functions":[{"name":"getPos","desc":"The position at `alpha`. Alpha splits evenly across curves, so with 4 curves, 0.25 is the end of the first.\\nSince curves have different lengths, equal alpha steps don\'t move at a constant speed; use\\n[CubicSpline:getUniformPos] or [CubicSpline:getPosAtDistance] for that.","params":[{"name":"alpha","desc":"From 0 (the start) to 1 (the end). Clamped.","lua_type":"number"}],"returns":[{"desc":"","lua_type":"vector"}],"function_type":"method","errors":[{"lua_type":"\\"Spline doesn\'t have enough points to make a curve\\"","desc":"If the spline has no curves."}],"source":{"line":469,"path":"src/CubicSpline.luau"}},{"name":"sample","desc":"`count` positions at evenly spaced alphas, including both ends. Faster than calling [CubicSpline:getPos] in a\\nloop. Use [CubicSpline:sampleUniform] for positions evenly spaced along the length instead.","params":[{"name":"count","desc":"","lua_type":"number"},{"name":"out","desc":"A list to fill instead of making a new one. Anything past `count` is removed.","lua_type":"{vector}?"}],"returns":[{"desc":"`out`, if given.","lua_type":"{vector}"}],"function_type":"method","errors":[{"lua_type":"\\"Spline doesn\'t have enough points to make a curve\\"","desc":"If the spline has no curves."}],"source":{"line":488,"path":"src/CubicSpline.luau"}},{"name":"getLength","desc":"The length along the spline, or 0 if it has no curves.","params":[],"returns":[{"desc":"","lua_type":"number"}],"function_type":"method","source":{"line":514,"path":"src/CubicSpline.luau"}},{"name":"getAlphaAtDistance","desc":"The alpha at which `distance` along the spline has been travelled.","params":[{"name":"distance","desc":"Studs from the start. Clamped to the length.","lua_type":"number"},{"name":"hint","desc":"The hint returned by the previous lookup on this spline, if any.","lua_type":"number?"}],"returns":[{"desc":"The alpha, as used by [CubicSpline:getPos].","lua_type":"number"},{"desc":"A hint for the next lookup.","lua_type":"number"}],"function_type":"method","errors":[{"lua_type":"\\"Spline doesn\'t have enough points to make a curve\\"","desc":"If the spline has no curves."}],"source":{"line":533,"path":"src/CubicSpline.luau"}},{"name":"getPosAtDistance","desc":"The position `distance` studs along the spline. This is the call to use for things moving at a constant\\nspeed: keep a distance, add `speed * deltaTime` to it every frame, and pass back the hint from the last call.\\n\\n```lua\\nlocal distance, hint = 0, nil\\nRunService.Heartbeat:Connect(function(deltaTime)\\n    distance = (distance + speed * deltaTime) % spline:getLength()\\n    local position\\n    position, hint = spline:getPosAtDistance(distance, hint)\\nend)\\n```","params":[{"name":"distance","desc":"Studs from the start. Clamped to the length.","lua_type":"number"},{"name":"hint","desc":"The hint returned by the previous lookup on this spline, if any.","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"vector"},{"desc":"A hint for the next lookup.","lua_type":"number"}],"function_type":"method","errors":[{"lua_type":"\\"Spline doesn\'t have enough points to make a curve\\"","desc":"If the spline has no curves."}],"source":{"line":559,"path":"src/CubicSpline.luau"}},{"name":"getUniformPos","desc":"Like [CubicSpline:getPos], but alpha is a fraction of the length, so equal alpha steps move at a constant\\nspeed. The same as [CubicSpline:getPosAtDistance] with `alpha * length`.","params":[{"name":"alpha","desc":"From 0 (the start) to 1 (the end), as a fraction of the length. Clamped.","lua_type":"number"},{"name":"hint","desc":"The hint returned by the previous lookup on this spline, if any.","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"vector"},{"desc":"A hint for the next lookup.","lua_type":"number"}],"function_type":"method","errors":[{"lua_type":"\\"Spline doesn\'t have enough points to make a curve\\"","desc":"If the spline has no curves."}],"source":{"line":620,"path":"src/CubicSpline.luau"}},{"name":"getDirectionAtDistance","desc":"The direction of travel `distance` studs along the spline. Where the curve stops for an instant, like the ends\\nof a Hermite curve with no velocity, it\'s the direction the curve moves through the stop. A spline with no\\nlength at all has a zero direction.","params":[{"name":"distance","desc":"Studs from the start. Clamped to the length.","lua_type":"number"},{"name":"hint","desc":"The hint returned by the previous lookup on this spline, if any.","lua_type":"number?"}],"returns":[{"desc":"A unit vector.","lua_type":"vector"},{"desc":"A hint for the next lookup.","lua_type":"number"}],"function_type":"method","errors":[{"lua_type":"\\"Spline doesn\'t have enough points to make a curve\\"","desc":"If the spline has no curves."}],"source":{"line":637,"path":"src/CubicSpline.luau"}},{"name":"getPosAndDirectionAtDistance","desc":"[CubicSpline:getPosAtDistance] and [CubicSpline:getDirectionAtDistance] from one lookup.","params":[{"name":"distance","desc":"Studs from the start. Clamped to the length.","lua_type":"number"},{"name":"hint","desc":"The hint returned by the previous lookup on this spline, if any.","lua_type":"number?"}],"returns":[{"desc":"The position.","lua_type":"vector"},{"desc":"The direction of travel, as in [CubicSpline:getDirectionAtDistance].","lua_type":"vector"},{"desc":"A hint for the next lookup.","lua_type":"number"}],"function_type":"method","errors":[{"lua_type":"\\"Spline doesn\'t have enough points to make a curve\\"","desc":"If the spline has no curves."}],"source":{"line":654,"path":"src/CubicSpline.luau"}},{"name":"getOffsetPosAtDistance","desc":"The position `offset` studs to the side of the spline, `distance` studs along it, for things that walk beside\\nthe path instead of on it. The side is horizontal, so the height stays the spline\'s. Straight up or down has no\\nhorizontal side, so there it keeps the side of the nearest part of the spline that isn\'t vertical: a climb that\\nbends up and over in one vertical plane keeps the same side the whole way.\\n\\nOffset positions jump at sharp corners, where the side flips from one line\'s to the next. On a rounded corner\\nthey move smoothly as long as the offset is smaller than the arc\'s radius. For [Splynx.rounded] that\'s\\n`reach / tan(turn / 2)`: the reach at a right angle, and less for sharper turns.","params":[{"name":"distance","desc":"Studs from the start. Clamped to the length.","lua_type":"number"},{"name":"offset","desc":"Studs to the right of the direction of travel; negative is to the left.","lua_type":"number"},{"name":"hint","desc":"The hint returned by the previous lookup on this spline, if any.","lua_type":"number?"}],"returns":[{"desc":"The offset position.","lua_type":"vector"},{"desc":"The spline\'s direction of travel there, as in [CubicSpline:getDirectionAtDistance].","lua_type":"vector"},{"desc":"A hint for the next lookup.","lua_type":"number"}],"function_type":"method","errors":[{"lua_type":"\\"Spline doesn\'t have enough points to make a curve\\"","desc":"If the spline has no curves."}],"source":{"line":743,"path":"src/CubicSpline.luau"}},{"name":"getPosAtDistances","desc":"Many lookups in one call, written into lists you keep, so nothing new is made. Meant for many things moving\\nalong the same spline: keep their distances (and offsets) in lists, and pass the same hints list every frame.\\n\\n```lua\\nlocal distances, positions, directions, hints = {}, {}, {}, {}\\nRunService.Heartbeat:Connect(function(deltaTime)\\n    for i, distance in distances do\\n        distances[i] = distance + speed * deltaTime\\n    end\\n    spline:getPosAtDistances(distances, positions, directions, nil, hints)\\nend)\\n```","params":[{"name":"distances","desc":"Studs from the start, one per lookup. Clamped to the length.","lua_type":"{number}"},{"name":"outPositions","desc":"Filled with the position for each distance.","lua_type":"{vector}"},{"name":"outDirections","desc":"Filled with the direction of travel for each distance.","lua_type":"{vector}?"},{"name":"offsets","desc":"One per distance: studs to the right, as in [CubicSpline:getOffsetPosAtDistance].","lua_type":"{number}?"},{"name":"hints","desc":"One per distance, read and then replaced with the hint for the next call.","lua_type":"{number}?"}],"returns":[],"function_type":"method","errors":[{"lua_type":"\\"Spline doesn\'t have enough points to make a curve\\"","desc":"If the spline has no curves."}],"source":{"line":839,"path":"src/CubicSpline.luau"}},{"name":"sampleUniform","desc":"`count` positions evenly spaced along the length, including both ends. Faster than calling\\n[CubicSpline:getPosAtDistance] in a loop.","params":[{"name":"count","desc":"","lua_type":"number"},{"name":"out","desc":"A list to fill instead of making a new one. Anything past `count` is removed.","lua_type":"{vector}?"}],"returns":[{"desc":"`out`, if given.","lua_type":"{vector}"}],"function_type":"method","errors":[{"lua_type":"\\"Spline doesn\'t have enough points to make a curve\\"","desc":"If the spline has no curves."}],"source":{"line":950,"path":"src/CubicSpline.luau"}},{"name":"getJoints","desc":"Where each curve starts, plus where the last one ends. For Bezier splines these are every third point; for\\nB-splines they\'re between the points.","params":[],"returns":[{"desc":"","lua_type":"{vector}"}],"function_type":"method","source":{"line":976,"path":"src/CubicSpline.luau"}},{"name":"getCurveCount","desc":"The number of curves the points make.","params":[],"returns":[{"desc":"","lua_type":"number"}],"function_type":"method","source":{"line":996,"path":"src/CubicSpline.luau"}},{"name":"getJointDistances","desc":"How far along the spline each of [CubicSpline:getJoints] is: 0, then the end of each curve.","params":[],"returns":[{"desc":"","lua_type":"{number}"}],"function_type":"method","source":{"line":1007,"path":"src/CubicSpline.luau"}},{"name":"getPoint","desc":"","params":[{"name":"index","desc":"","lua_type":"number"}],"returns":[{"desc":"Relative to the pivot.","lua_type":"vector"}],"function_type":"method","source":{"line":1024,"path":"src/CubicSpline.luau"}},{"name":"getPoints","desc":"A copy of the points. Change them through [CubicSpline:setPoint] and friends so the spline stays up to date.","params":[],"returns":[{"desc":"Relative to the pivot.","lua_type":"{vector}"}],"function_type":"method","source":{"line":1035,"path":"src/CubicSpline.luau"}},{"name":"setPoint","desc":"Moves one point. Only the curves that use it are rebuilt.","params":[{"name":"index","desc":"","lua_type":"number"},{"name":"position","desc":"Relative to the pivot.","lua_type":"VectorLike"}],"returns":[],"function_type":"method","errors":[{"lua_type":"\\"No point at index ...\\"","desc":"If there\'s no point at `index`."}],"source":{"line":1048,"path":"src/CubicSpline.luau"}},{"name":"setPoints","desc":"Replaces every point. Hermite splines keep their velocities in order, adding zero velocities for new points,\\nand rounded splines do the same with their radii.","params":[{"name":"points","desc":"Relative to the pivot.","lua_type":"{VectorLike}"}],"returns":[],"function_type":"method","source":{"line":1062,"path":"src/CubicSpline.luau"}},{"name":"addPoints","desc":"Adds points to the end. Existing curves keep their tables unless the new points change them. On a rounded\\nspline the new points get the radius it was made with, or 0 if it was made with a list of radii.","params":[{"name":"points","desc":"Relative to the pivot.","lua_type":"{VectorLike}"},{"name":"velocities","desc":"Hermite splines only: one per added point. Missing ones are zero.","lua_type":"{VectorLike}?"}],"returns":[],"function_type":"method","source":{"line":1077,"path":"src/CubicSpline.luau"}},{"name":"removePoints","desc":"Removes several points at once.","params":[{"name":"indices","desc":"In any order. Repeated indices are removed once.","lua_type":"{number}"}],"returns":[],"function_type":"method","source":{"line":1106,"path":"src/CubicSpline.luau"}},{"name":"removePoint","desc":"","params":[{"name":"index","desc":"","lua_type":"number"}],"returns":[],"function_type":"method","source":{"line":1132,"path":"src/CubicSpline.luau"}},{"name":"getPivot","desc":"","params":[],"returns":[{"desc":"","lua_type":"vector"}],"function_type":"method","source":{"line":1141,"path":"src/CubicSpline.luau"}},{"name":"setPivot","desc":"Moves the whole spline. Points stay the same relative to the pivot, so nothing needs rebuilding.","params":[{"name":"pivot","desc":"","lua_type":"VectorLike"}],"returns":[],"function_type":"method","source":{"line":1152,"path":"src/CubicSpline.luau"}},{"name":"getVelocity","desc":"The velocity at a point: a Hermite spline\'s own, or the one a Cardinal spline derives from the neighbours.\\nFor the direction of the curve partway along, use [CubicSpline:getDirectionAtDistance].","params":[{"name":"index","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"vector"}],"function_type":"method","errors":[{"lua_type":"\\"Only Hermite and Cardinal splines have velocities\\"","desc":"On other spline types."}],"source":{"line":1166,"path":"src/CubicSpline.luau"}},{"name":"setVelocity","desc":"Changes a Hermite spline\'s velocity at a point. Only the curves either side of it are rebuilt.","params":[{"name":"index","desc":"","lua_type":"number"},{"name":"velocity","desc":"","lua_type":"VectorLike"}],"returns":[],"function_type":"method","errors":[{"lua_type":"\\"Only Hermite splines have settable velocities\\"","desc":"On other spline types."},{"lua_type":"\\"No point at index ...\\"","desc":"If there\'s no point at `index`."}],"source":{"line":1186,"path":"src/CubicSpline.luau"}},{"name":"getScale","desc":"A Cardinal spline\'s scale.","params":[],"returns":[{"desc":"","lua_type":"number"}],"function_type":"method","source":{"line":1201,"path":"src/CubicSpline.luau"}},{"name":"setScale","desc":"Changes a Cardinal spline\'s scale, which reshapes every curve.","params":[{"name":"scale","desc":"","lua_type":"number"}],"returns":[],"function_type":"method","errors":[{"lua_type":"\\"Only Cardinal splines have a scale\\"","desc":"On other spline types."}],"source":{"line":1213,"path":"src/CubicSpline.luau"}},{"name":"getRadius","desc":"The size a rounded or filleted spline asks for at a point\'s corner: its reach for [Splynx.rounded], its radius\\nfor [Splynx.filleted]. The corner gets less if the arc wouldn\'t fit.","params":[{"name":"index","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"method","errors":[{"lua_type":"\\"Only rounded and filleted splines have radii\\"","desc":"On other spline types."}],"source":{"line":1229,"path":"src/CubicSpline.luau"}},{"name":"setRadius","desc":"Changes the size of a rounded or filleted spline\'s corner at a point, as in [CubicSpline:getRadius]. Only the\\nnearby curves are rebuilt.","params":[{"name":"index","desc":"","lua_type":"number"},{"name":"radius","desc":"","lua_type":"number"}],"returns":[],"function_type":"method","errors":[{"lua_type":"\\"Only rounded and filleted splines have radii\\"","desc":"On other spline types."},{"lua_type":"\\"No point at index ...\\"","desc":"If there\'s no point at `index`."}],"source":{"line":1246,"path":"src/CubicSpline.luau"}}],"properties":[],"types":[],"name":"CubicSpline","desc":"Smooth curves, made by [Splynx.bezier], [Splynx.hermite], [Splynx.cardinal], [Splynx.catmullRom],\\n[Splynx.bSpline], [Splynx.rounded] and [Splynx.filleted]. Every type is stored the same way, as one cubic\\npolynomial per curve, so they all cost the same to query; they only differ in how points become curves.\\n\\nDistance lookups use a table per curve that maps evenly spaced distances to alphas. It\'s built the first\\ntime a distance lookup or [CubicSpline:getLength] needs it, and rebuilt for the curves an edit changes, so\\nan edit followed by a distance lookup costs a few microseconds. Positions are within about 0.0005 studs of\\nthe true distance.","source":{"line":60,"path":"src/CubicSpline.luau"}}')}}]);